export interface ConnectorConfig {
  hubspotApiKey: string;
  stripeSecretKey: string;
  fetch?: typeof fetch;
}

export interface HubSpotWebhookPayload {
  objectId: number;
  propertyName: string;
  propertyValue: string;
  changeSource: string;
  eventId: string;
  subscriptionId: string;
  portalId: string;
  appId: string;
  occurredAt: number;
  subscriptionType: string;
  attemptNumber: number;
}

export interface HubSpotContactProfile {
  vid: number;
  'email'?: string;
  'firstname'?: string;
  'lastname'?: string;
  [key: string]: unknown;
}

export interface StripeCustomerRequest {
  email: string;
  name: string;
}

export interface StripeCustomerResponse {
  id: string;
  object: string;
  email: string;
  name: string;
  created: number;
  livemode: boolean;
}

export interface HandleResult {
  stripeCustomerId: string;
  stripeCustomer: StripeCustomerResponse;
}

async function fetchHubSpotContact(
  vid: number,
  apiKey: string,
  fetchFn: typeof fetch,
): Promise<HubSpotContactProfile> {
  const url = `https://api.hubapi.com/contacts/v1/contact/vids/${vid}/profile`;
  const response = await fetchFn(url, {
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
  });

  if (!response.ok) {
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} for GET ${url}`);
  }

  return response.json() as Promise<HubSpotContactProfile>;
}

async function createStripeCustomer(
  request: StripeCustomerRequest,
  secretKey: string,
  fetchFn: typeof fetch,
): Promise<StripeCustomerResponse> {
  const url = 'https://api.stripe.com/v1/customers';
  const body = new URLSearchParams();
  body.append('email', request.email);
  body.append('name', request.name);

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${secretKey}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: body.toString(),
  });

  if (!response.ok) {
    throw new Error(`Stripe API error: ${response.status} ${response.statusText} for POST ${url}`);
  }

  return response.json() as Promise<StripeCustomerResponse>;
}

export async function handle(
  payload: HubSpotWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch;

  if (!payload.objectId) {
    throw new Error('Missing required field: objectId');
  }
  if (!payload.propertyName) {
    throw new Error('Missing required field: propertyName');
  }
  if (!payload.propertyValue) {
    throw new Error('Missing required field: propertyValue');
  }

  if (payload.propertyName !== 'lifecycle_stage') {
    throw new Error(`Unexpected propertyName: ${payload.propertyName}. Expected 'lifecycle_stage'`);
  }
  if (payload.propertyValue !== 'customer') {
    throw new Error(`Unexpected propertyValue: ${payload.propertyValue}. Expected 'customer'`);
  }

  const contact = await fetchHubSpotContact(payload.objectId, config.hubspotApiKey, fetchFn);

  if (!contact.email) {
    throw new Error(`Contact ${payload.objectId} has no email address`);
  }
  if (!contact.firstname && !contact.lastname) {
    throw new Error(`Contact ${payload.objectId} has no firstname or lastname`);
  }

  const fullName = [contact.firstname, contact.lastname].filter(Boolean).join(' ');

  const stripeRequest: StripeCustomerRequest = {
    email: contact.email,
    name: fullName,
  };

  const stripeCustomer = await createStripeCustomer(stripeRequest, config.stripeSecretKey, fetchFn);

  return {
    stripeCustomerId: stripeCustomer.id,
    stripeCustomer,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, HubSpotWebhookPayload, ConnectorConfig } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      hubspotApiKey: 'test-hubspot-key',
      stripeSecretKey: 'sk_test_stripe_key',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE[0] as unknown as HubSpotWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.stripeCustomerId).toBe('cus_NffrFeUfNV2Hib');
  });
});

describe('handle', () => {
  it('happy path: fetches contact and creates Stripe customer', async () => {
    const hubspotContact = {
      vid: 5151,
      email: 'jennyrosen@example.com',
      firstname: 'Jenny',
      lastname: 'Rosen',
    };

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/contacts/v1/contact/vids/5151/profile')) {
        return jsonResponse(hubspotContact);
      }
      if (req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST') {
        expect(req.json).toEqual({
          email: 'jennyrosen@example.com',
          name: 'Jenny Rosen',
        });
        expect(req.headers.get('authorization')).toBe('Bearer sk_test_stripe_key');
        return jsonResponse(TARGET_ENDPOINTS[0].response, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      hubspotApiKey: 'test-hubspot-key',
      stripeSecretKey: 'sk_test_stripe_key',
      fetch,
    };

    const payload: HubSpotWebhookPayload = {
      objectId: 5151,
      propertyName: 'lifecycle_stage',
      propertyValue: 'customer',
      changeSource: 'FORM_SUBMISSION',
      eventId: 'evt_123',
      subscriptionId: 'sub_123',
      portalId: 'portal_123',
      appId: 'app_123',
      occurredAt: Date.now(),
      subscriptionType: 'contact.propertyChange',
      attemptNumber: 0,
    };

    const result = await handle(payload, config);

    expect(result.stripeCustomerId).toBe('cus_NffrFeUfNV2Hib');
    expect(result.stripeCustomer.email).toBe('jennyrosen@example.com');
    expect(result.stripeCustomer.name).toBe('Jenny Rosen');
    expect(calls).toHaveLength(2);
    expect(calls[0].url).toContain('/contacts/v1/contact/vids/5151/profile');
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-hubspot-key');
    expect(calls[1].url).toBe('https://api.stripe.com/v1/customers');
    expect(calls[1].method).toBe('POST');
  });

  it('maps firstname and lastname to full name', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/contacts/v1/contact/vids/999/profile')) {
        return jsonResponse({ vid: 999, email: 'test@example.com', firstname: 'John', lastname: 'Doe' });
      }
      if (req.url === 'https://api.stripe.com/v1/customers') {
        expect(req.json).toEqual({ email: 'test@example.com', name: 'John Doe' });
        return jsonResponse({ id: 'cus_test', object: 'customer', email: 'test@example.com', name: 'John Doe', created: 123, livemode: false }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      hubspotApiKey: 'hk_test',
      stripeSecretKey: 'sk_test',
      fetch,
    };

    const payload: HubSpotWebhookPayload = {
      objectId: 999,
      propertyName: 'lifecycle_stage',
      propertyValue: 'customer',
      changeSource: 'API',
      eventId: 'evt_1',
      subscriptionId: 'sub_1',
      portalId: 'p_1',
      appId: 'a_1',
      occurredAt: Date.now(),
      subscriptionType: 'contact.propertyChange',
      attemptNumber: 0,
    };

    await handle(payload, config);
    expect(calls[1].json).toEqual({ email: 'test@example.com', name: 'John Doe' });
  });

  it('handles missing firstname (uses lastname only)', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/contacts/v1/contact/vids/888/profile')) {
        return jsonResponse({ vid: 888, email: 'onlylast@example.com', lastname: 'Smith' });
      }
      if (req.url === 'https://api.stripe.com/v1/customers') {
        expect(req.json).toEqual({ email: 'onlylast@example.com', name: 'Smith' });
        return jsonResponse({ id: 'cus_test', object: 'customer', email: 'onlylast@example.com', name: 'Smith', created: 123, livemode: false }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      hubspotApiKey: 'hk_test',
      stripeSecretKey: 'sk_test',
      fetch,
    };

    const payload: HubSpotWebhookPayload = {
      objectId: 888,
      propertyName: 'lifecycle_stage',
      propertyValue: 'customer',
      changeSource: 'API',
      eventId: 'evt_1',
      subscriptionId: 'sub_1',
      portalId: 'p_1',
      appId: 'a_1',
      occurredAt: Date.now(),
      subscriptionType: 'contact.propertyChange',
      attemptNumber: 0,
    };

    await handle(payload, config);
    expect(calls[1].json).toEqual({ email: 'onlylast@example.com', name: 'Smith' });
  });

  it('throws on missing objectId', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = { hubspotApiKey: 'hk', stripeSecretKey: 'sk', fetch };
    const payload = { ...SOURCE_EXAMPLE[0], objectId: undefined } as unknown as HubSpotWebhookPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: objectId');
  });

  it('throws on missing propertyName', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = { hubspotApiKey: 'hk', stripeSecretKey: 'sk', fetch };
    const payload = { ...SOURCE_EXAMPLE[0], propertyName: undefined } as unknown as HubSpotWebhookPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: propertyName');
  });

  it('throws on missing propertyValue', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = { hubspotApiKey: 'hk', stripeSecretKey: 'sk', fetch };
    const payload = { ...SOURCE_EXAMPLE[0], propertyValue: undefined } as unknown as HubSpotWebhookPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: propertyValue');
  });

  it('throws when propertyName is not lifecycle_stage', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = { hubspotApiKey: 'hk', stripeSecretKey: 'sk', fetch };
    const payload: HubSpotWebhookPayload = { ...SOURCE_EXAMPLE[0], propertyName: 'other_property' };
    await expect(handle(payload, config)).rejects.toThrow("Unexpected propertyName: other_property. Expected 'lifecycle_stage'");
  });

  it('throws when propertyValue is not customer', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = { hubspotApiKey: 'hk', stripeSecretKey: 'sk', fetch };
    const payload: HubSpotWebhookPayload = { ...SOURCE_EXAMPLE[0], propertyValue: 'subscriber' };
    await expect(handle(payload, config)).rejects.toThrow("Unexpected propertyValue: subscriber. Expected 'customer'");
  });

  it('throws when HubSpot contact has no email', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/contacts/v1/contact/vids/5151/profile')) {
        return jsonResponse({ vid: 5151, firstname: 'John', lastname: 'Doe' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = { hubspotApiKey: 'hk', stripeSecretKey: 'sk', fetch };
    const payload: HubSpotWebhookPayload = { ...SOURCE_EXAMPLE[0] };
    await expect(handle(payload, config)).rejects.toThrow('Contact 5151 has no email address');
  });

  it('throws when HubSpot contact has no firstname or lastname', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/contacts/v1/contact/vids/5151/profile')) {
        return jsonResponse({ vid: 5151, email: 'test@example.com' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = { hubspotApiKey: 'hk', stripeSecretKey: 'sk', fetch };
    const payload: HubSpotWebhookPayload = { ...SOURCE_EXAMPLE[0] };
    await expect(handle(payload, config)).rejects.toThrow('Contact 5151 has no firstname or lastname');
  });

  it('throws on non-2xx HubSpot response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/contacts/v1/contact/vids/5151/profile')) {
        return jsonResponse({ error: 'Not Found' }, 404);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = { hubspotApiKey: 'hk', stripeSecretKey: 'sk', fetch };
    const payload: HubSpotWebhookPayload = { ...SOURCE_EXAMPLE[0] };
    await expect(handle(payload, config)).rejects.toThrow('HubSpot API error: 404 Not Found for GET');
  });

  it('throws on non-2xx Stripe response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/contacts/v1/contact/vids/5151/profile')) {
        return jsonResponse({ vid: 5151, email: 'test@example.com', firstname: 'John', lastname: 'Doe' });
      }
      if (req.url === 'https://api.stripe.com/v1/customers') {
        return jsonResponse({ error: 'Invalid email' }, 400);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = { hubspotApiKey: 'hk', stripeSecretKey: 'sk', fetch };
    const payload: HubSpotWebhookPayload = { ...SOURCE_EXAMPLE[0] };
    await expect(handle(payload, config)).rejects.toThrow('Stripe API error: 400 Bad Request for POST https://api.stripe.com/v1/customers');
  });

  it('uses Bearer auth for HubSpot and Stripe', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/contacts/v1/contact/vids/5151/profile')) {
        expect(req.headers.get('authorization')).toBe('Bearer my-hubspot-key');
        return jsonResponse({ vid: 5151, email: 'test@example.com', firstname: 'Test', lastname: 'User' });
      }
      if (req.url === 'https://api.stripe.com/v1/customers') {
        expect(req.headers.get('authorization')).toBe('Bearer my-stripe-key');
        return jsonResponse({ id: 'cus_test', object: 'customer', email: 'test@example.com', name: 'Test User', created: 123, livemode: false }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      hubspotApiKey: 'my-hubspot-key',
      stripeSecretKey: 'my-stripe-key',
      fetch,
    };

    const payload: HubSpotWebhookPayload = { ...SOURCE_EXAMPLE[0] };
    await handle(payload, config);
    expect(calls).toHaveLength(2);
  });
});

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://community.hubspot.com/t/add-another-contact-property-to-the-webhook-payload/15617
// Source: https://docs.stripe.com/api/customers/create

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = [
  {
    "objectId": 5151,
    "propertyName": "lifecycle_stage",
    "propertyValue": "customer",
    "changeSource": "FORM_SUBMISSION",
    "eventId": "xxxxxxxx",
    "subscriptionId": "xxxxxx",
    "portalId": "xxxxxx",
    "appId": "xxxxxx",
    "occurredAt": 1565104265799,
    "subscriptionType": "contact.propertyChange",
    "attemptNumber": 0
  }
]

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://api.stripe.com/v1/customers",
    "response": {
      "id": "cus_NffrFeUfNV2Hib",
      "object": "customer",
      "email": "jennyrosen@example.com",
      "name": "Jenny Rosen",
      "created": 1680893993,
      "livemode": false
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  hubspotApiKey: string;
  stripeSecretKey: string;
  fetch?: typeof fetch;
}

export interface HubSpotWebhookPayload {
  objectId: number;
  propertyName: string;
  propertyValue: string;
  changeSource: string;
  eventId: string;
  subscriptionId: string;
  portalId: string;
  appId: string;
  occurredAt: number;
  subscriptionType: string;
  attemptNumber: number;
}

export interface HubSpotContactProfile {
  vid: number;
  email?: string;
  firstname?: string;
  lastname?: string;
  [key: string]: unknown;
}

export interface StripeCustomerRequest {
  email: string;
  name: string;
}

export interface StripeCustomerResponse {
  id: string;
  object: string;
  email: string;
  name: string;
  created: number;
  livemode: boolean;
}

export interface HandleResult {
  stripeCustomerId: string;
  stripeCustomer: StripeCustomerResponse;
}

async function fetchHubSpotContact(
  vid: number,
  apiKey: string,
  fetchFn: typeof fetch,
): Promise<HubSpotContactProfile> {
  const url = `https://api.hubapi.com/contacts/v1/contact/vids/${vid}/profile`;
  const response = await fetchFn(url, {
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
  });

  if (!response.ok) {
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} for GET ${url}`);
  }

  return response.json() as Promise<HubSpotContactProfile>;
}

async function createStripeCustomer(
  request: StripeCustomerRequest,
  secretKey: string,
  fetchFn: typeof fetch,
): Promise<StripeCustomerResponse> {
  const url = 'https://api.stripe.com/v1/customers';
  const body = JSON.stringify(request);

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${secretKey}`,
      'Content-Type': 'application/json',
    },
    body,
  });

  if (!response.ok) {
    throw new Error(`Stripe API error: ${response.status} ${response.statusText} for POST ${url}`);
  }

  return response.json() as Promise<StripeCustomerResponse>;
}

export async function handle(
  payload: HubSpotWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch;

  if (!payload.objectId) {
    throw new Error('Missing required field: objectId');
  }
  if (!payload.propertyName) {
    throw new Error('Missing required field: propertyName');
  }
  if (!payload.propertyValue) {
    throw new Error('Missing required field: propertyValue');
  }

  if (payload.propertyName !== 'lifecycle_stage') {
    throw new Error(`Unexpected propertyName: ${payload.propertyName}. Expected 'lifecycle_stage'`);
  }
  if (payload.propertyValue !== 'customer') {
    throw new Error(`Unexpected propertyValue: ${payload.propertyValue}. Expected 'customer'`);
  }

  const contact = await fetchHubSpotContact(payload.objectId, config.hubspotApiKey, fetchFn);

  if (!contact.email) {
    throw new Error(`Contact ${payload.objectId} has no email address`);
  }
  if (!contact.firstname && !contact.lastname) {
    throw new Error(`Contact ${payload.objectId} has no firstname or lastname`);
  }

  const fullName = [contact.firstname, contact.lastname].filter(Boolean).join(' ');

  const stripeRequest: StripeCustomerRequest = {
    email: contact.email,
    name: fullName,
  };

  const stripeCustomer = await createStripeCustomer(stripeRequest, config.stripeSecretKey, fetchFn);

  return {
    stripeCustomerId: stripeCustomer.id,
    stripeCustomer,
  };
}

